import { test, expect } from '@playwright/test';

test.describe('Notification Bell Badge Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display correct badge count on notification bell icon', async ({ page }) => {
    // Verify notification bell icon is visible
    const bellIcon = page.getByRole('button', { name: /notification bell/i });
    await expect(bellIcon).toBeVisible();

    // Verify badge count is displayed
    const badgeCount = page.getByText(/3 notifications/i);
    await expect(badgeCount).toBeVisible();

    // Verify badge count is accurate
    const actualCount = page.getByText(/3 notifications/i);
    const expectedCount = page.getByText(/3 notifications/i);
    await expect(actualCount).toBeVisible();
    await expect(expectedCount).toBeVisible();

    // Verify badge color is correct
    const badgeColor = page.getByRole('status', { name: /notifications/i });
    await expect(badgeColor).toHaveAttribute('data-badge-color', 'red');

    // Verify notification bell icon has correct aria-label
    await expect(bellIcon).toHaveAttribute('aria-label', 'Notification bell');

    // Verify notification bell icon has correct aria-pressed state
    await expect(bellIcon).toHaveAttribute('aria-pressed', 'false');
  });

  test('should update badge count when notifications are received', async ({ page }) => {
    // Verify initial badge count is 0
    const initialBadgeCount = page.getByText(/0 notifications/i);
    await expect(initialBadgeCount).toBeVisible();

    // Mock API call to receive notifications
    await page.route('**/api/notifications', (route) => {
      route.continue();
    });

    // Verify notification bell icon is still visible
    const bellIcon = page.getByRole('button', { name: /notification bell/i });
    await expect(bellIcon).toBeVisible();

    // Verify badge count updates to 1
    const updatedBadgeCount = page.getByText(/1 notification/i);
    await expect(updatedBadgeCount).toBeVisible();

    // Verify badge color is still correct
    const badgeColor = page.getByRole('status', { name: /notifications/i });
    await expect(badgeColor).toHaveAttribute('data-badge-color', 'red');

    // Verify notification bell icon has correct aria-pressed state
    await expect(bellIcon).toHaveAttribute('aria-pressed', 'true');
  });
});
